// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserRewardGrant) predicate.UserRewardGrant {
	return predicate.UserRewardGrant(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserRewardGrant) predicate.UserRewardGrant {
	return predicate.UserRewardGrant(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserRewardGrant) predicate.UserRewardGrant {
	return predicate.UserRewardGrant(sql.NotPredicates(p))
}
